fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len() as isize - 1; // Use isize for easier calculations with -1

    while left <= right {
        let mid = (left + right) / 2;
        if arr[mid as usize] < target {
            left = mid + 1;
        } else if arr[mid as usize] > target {
            right = mid - 1;
        } else {
            // Found the target, now check for the first occurrence
            if mid == 0 || arr[mid as usize - 1] < target {
                return Some(mid as usize);
            }
            right = mid - 1; // Continue searching in the left half
        }
    }

    None // Target not found
}